        v_without_build = v.split('+')[0]

        # Split by '-' to separate core version and pre-release
        if '-' in v_without_build:
            core, prerelease = v_without_build.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            core = v_without_build
            prerelease_parts = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        return (major, minor, patch, prerelease_parts)

    def prerelease_key(prerelease_parts):
        # If no pre-release, it sorts after pre-release versions
        if prerelease_parts is None:
            return (1,)  # 1 indicates no pre-release (sorts after 0)

        # Convert pre-release parts to comparable format
        key_parts = []
        for part in prerelease_parts:
            if part.isdigit():
                # Numeric identifiers: (0, numeric_value) - sorts before non-numeric
                key_parts.append((0, int(part)))
            else:
                # Non-numeric identifiers: (1, string_value) - sorts after numeric
                key_parts.append((1, part))

        # Return tuple: (0, tuple_of_parts) for pre-release
        # This ensures fewer identifiers sort first when all shared are equal
        return (0, tuple(key_parts))

    def sort_key(v):
        major, minor, patch, prerelease_parts = parse_version(v)
        return (major, minor, patch, prerelease_key(prerelease_parts))

    # Use stable sort to maintain input order for equal precedence versions
    return sorted(versions, key=sort_key)

